-- Web Revenue (May 2026)
SELECT SUM(amount_usd) FROM payments 
WHERE status = 'succeeded' AND paid_at >= '2026-05-01'::TIMESTAMPTZ AND paid_at < '2026-06-01'::TIMESTAMPTZ;

-- Store Revenue (May 2026)
SELECT SUM(proceeds_usd) FROM store_transactions 
WHERE purchased_at >= '2026-05-01'::TIMESTAMPTZ AND purchased_at < '2026-06-01'::TIMESTAMPTZ;

-- Refunds (May 2026)
SELECT SUM(amount_usd) FROM refunds r JOIN payments p ON r.payment_id = p.payment_id 
WHERE r.refunded_at >= '2026-05-01'::TIMESTAMPTZ AND r.refunded_at < '2026-06-01'::TIMESTAMPTZ;

